L15_1.m_Pos = "L"
L16_1 = "하지만 변하는 게 없더라도, 숨겨선 안되는 게 있으니까."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "でも変わることはないとしても、隠してはいけないものはあるから。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But even if nothing changes, there are things that shouldn't be hidden."
L15_1.m_Talk_ENG = L16_1
L16_1 = "但即便沒法改變，也有不能隱藏的東西。"
