L18_1 = "RITA_ANAP_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "나 역시 수많은 피를 손에 묻혔고, 그걸 변명할 생각은 없어."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "私の手も数えきれない程の血で染まっているし、それについて言い訳するつもりはない。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I, too, have stained my hands with the blood of countless lives. And I have no intention of making excuses for it."
L17_1.m_Talk_ENG = L18_1
L18_1 = "我的雙手也沾染著無數鮮血，我也不打算辯解。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "I, too, have stained my hands with the blood of countless lives. And I have no intention of making excuses for it."
L17_1.m_Talk_DEU = L18_1
L18_1 = "I, too, have stained my hands with the blood of countless lives. And I have no intention of making excuses for it."
