L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "죄라는 건, 섭리와 함께 공존하는 거다. 이미 벌어진 일은 돌이킬 수 없다는 섭리..."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "罪というものは、摂理とともにあるもの。すでに起きたことは取り戻せないという摂理……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Sin coexists with the laws of the world. The law that what's already happened can't be undone..."
L19_1.m_Talk_ENG = L20_1
L20_1 = "罪與法則共存，已發生的事無法復原的法則……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "Sin coexists with the laws of the world. The law that what's already happened can't be undone..."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Sin coexists with the laws of the world. The law that what's already happened can't be undone..."
L19_1.m_Talk_FRA = L20_1
