L20_1.m_Pos = "R"
L21_1 = "하지만 죽음이 없는 이곳에선 그런 섭리도 통하지 않아."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "だが、死のないここでそんな摂理も通じない。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "But in this place where death doesn't exist, even that law doesn't apply."
L20_1.m_Talk_ENG = L21_1
L21_1 = "但這裡沒有死亡，法則也失去意義。"
