L18_1 = "이 낙원이란 곳에선 아닐지 몰라도, 보통의 세상에서 목숨은 하나 뿐인 거니까."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ここ楽園とやらでは違うかもしれないけど、普通の世界で命は一つだけだからね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "The Promised Land might be different, but in an ordinary world a person only has one life."
L17_1.m_Talk_ENG = L18_1
L18_1 = "雖然在樂園這裡可能不一定如此。但在普通世界裡，人只有一條性命。"
