L22_1.m_Face = "UNIT_DESPAIR"
L22_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L22_1.m_Pos = "C"
L23_1 = "왜 죽었어야 할 내가 낙원이라 불리는 곳에서 눈을 떴는지, 당신은 왜 그렇게 어려진 모습으로 내 앞에 나타난 건지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "どうして死ぬべきだった私が楽園と呼ばれる場所で目覚めたのか、あなたはどうしてそんなに幼くなった姿で私の前に現れたのか。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Why I, who should have died, woke up in a place called the Promised Land, or why you appeared before me looking so young."
L22_1.m_Talk_ENG = L23_1
L23_1 = "為什麼本該死去的我，會在這個被稱為樂園的地方醒來，你為什麼會以那麼年輕的樣子出現在我面前。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "Why I, who should have died, woke up in a place called the Promised Land, or why you appeared before me looking so young."
L22_1.m_Talk_DEU = L23_1
