L23_1.m_Pos = "C"
L24_1 = "하지만 분명히 기억하는 건, 우리 둘 다 세상이 멸망하는 걸 막으려고 타기리온이라는 마왕에게 맞섰다는 거야."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "でもはっきりと覚えてるのは、私たち二人は世界が滅ぶのを阻止するために、タギリオンという魔王に立ち向かったってことだよ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But what I remember clearly is that both of us stood against a Demon Lord named Thagirion to stop the destruction of the world."
L23_1.m_Talk_ENG = L24_1
L24_1 = "但我記得很清楚，我們倆都是為了阻止世界毀滅，才去對抗那個叫塔基里翁的魔王。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "But what I remember clearly is that both of us stood against a Demon Lord named Thagirion to stop the destruction of the world."
L23_1.m_Talk_DEU = L24_1
L24_1 = "But what I remember clearly is that both of us stood against a Demon Lord named Thagirion to stop the destruction of the world."
