L26_1.m_Pos = "C"
L27_1 = "<color=#ffd34c>낙원이 있기 전의 세계</color>를 멸망시킨 마왕... 이라는 것은 알고 있습니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "<color=#ffd34c>楽園ができる前の世界</color>を滅ぼした魔王……ということは存じております。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I know that the Demon Lord who destroyed the <color=#ffd34c>world before the Promised Land existed</color> was called that..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我知道……他是摧毀<color=#ffd34c>樂園出現前的世界</color>的魔王。"
