L27_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L27_1.m_Pos = "C"
L28_1 = "하지만 소녀가 그런 존재와 싸운 기억은 전혀 없사옵니다."
L27_1.m_Talk_KOREA = L28_1
