L28_1.m_Pos = "C"
L29_1 = "나도 얼마 전까진 몰랐지만... 당신이 살던 세계가 존재하는 전부는 아니야."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私もついこの間までは知らなかったんだけど……あなたが住んでいた世界がすべてではないんだよ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Until recently, I didn't know either... but the world you lived in isn't the whole of existence."
L28_1.m_Talk_ENG = L29_1
L29_1 = "我直到不久前才知道……你生活的世界並不是全部。"
L28_1.m_Talk_TWN = L29_1
