L30_1 = "EP15_ACT1_INTERLUDE2@182#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 688
L29_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_LAUGH"
L29_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L29_1.m_Pos = "C"
L30_1 = "저 너머 어딘가엔 내가 태어난 세계가 있고, 그곳엔 많은 사람들이 살고 있지."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "その向こうのどこかには私が生まれた世界があって、そこにたくさんの人が住んでいる。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Somewhere beyond lies the world where I was born, where many people live."
L29_1.m_Talk_ENG = L30_1
L30_1 = "在那邊的某個地方，有我出生的世界、住著很多人。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "Somewhere beyond lies the world where I was born, where many people live."
