L31_1 = "그리고 마왕 타기리온은 지금 그곳을... 내 고향을 없애려 하고 있어."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そして魔王タギリオンは今その世界を……私の故郷を消そうとしてる。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "And the Demon Lord Thagirion is now trying to destroy that place... My home."
L30_1.m_Talk_ENG = L31_1
L31_1 = "而魔王塔基里翁現在正試圖……摧毀我的故鄉。"
