L35_1 = "그치만 다른 멀쩡한 세계가... 그것도 저희 세계를 멸망시킨 자에게 노려지고 있었다는 건 처음 알았습니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ですが、他に普通の世界が……それもわたくしたちの世界を滅亡させた者に狙われていたということは初めて知りました。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "But I never knew that another intact world... was also being targeted by the one who destroyed our world."
L34_1.m_Talk_ENG = L35_1
L35_1 = "但我也第一次知道……那個完好無缺的世界，也被毀滅我們世界的人盯上了。"
