L37_1 = "다른 세계가 당신의 세계처럼 되는 걸 막기 위해, 누구보다 오랫동안 타기리온을 쫓아 다녔어."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
