L45_1 = "세계를 멸망시키거나 사람을 해친 악인이 있었다 해도... 미워하는 건 무의미합니다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "世界を滅亡させたり、人に害をなした悪人がいたとしても……憎むことに意味がないのです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Even if there was a villain who destroyed worlds or harmed people... hating them is meaningless."
L44_1.m_Talk_ENG = L45_1
L45_1 = "即便有毀滅世界或傷害人的壞人……恨他也沒有意義。"
