L47_1.m_Talk_JPN = L48_1
L48_1 = "There were countless things I wanted to say, yet none of them could leave my mouth."
L47_1.m_Talk_ENG = L48_1
L48_1 = "雖然我腦中浮現無數話語，但一句話也說不出口。"
