L50_1 = "...마에스트로 네퀴티아라는 기억을 가진 내가 설득하고 있다는 사실에 부딪히자, 말문이 막혔다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "m_bTalkCenterFadeIn"
L49_1[L50_1] = true
L50_1 = "……マエストロ・ネキティアという記憶を持つ私が説得しているという事実にぶち当たり、何も言えなくなった。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "was trying to persuade the very person who had hated Thagirion more than anyone and fought to stop her... I found myself at a loss for words."
L49_1.m_Talk_ENG = L50_1
L50_1 = "……竟然是是擁有指揮家．莉奎蒂亞記憶的我……，一時間我說不出話。"
