L1_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L2_1 = "그녀와 같은 얼굴, 같은 이름을 가진 소녀를 다시 이 피투성이의 굴레로 끌어들이는 게 옳은 선택일까?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "m_bTalkCenterFadeIn"
L1_1[L2_1] = true
L2_1 = "彼女と同じ顔、同じ名前を持つ少女を再びこの血まみれのしがらみに引き込むのは正しい選択なのだろうか？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Would it really be right to drag a girl with the same face and name back into that blood-soaked cycle?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "那麼把一個和她外貌、名字都一樣的女孩再拉回這個血腥的世界，是對的選擇嗎？"
