L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "m_bTalkCenterFadeIn"
L2_1[L3_1] = true
L3_1 = "失ってしまったすべてを再び手にいれたこの楽園から……そんな彼女を冷たい現実に引っ張り出す必要があるのだろうか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "In the Promised Land, where everything once lost has returned to her embrace... Should I really pull her back into that cold reality?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "在重拾失去的一切的樂園……我真的需要把她拉回冰冷的現實嗎？"
