L28_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L29_1 = "침몰하는 천지의 중심에서, 그루터기만 남은 황금나무가 빛을 발하니-"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "m_bTalkCenterFadeIn"
L28_1[L29_1] = true
L29_1 = "沈没する天地の中心で、切り株だけになった黄金の木が光を放つと……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "At the center of the sinking heavens and earth, the Golden Tree that remained only as a stump shone with light..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "在沉沒的天地中心，只剩下木墩的黃金樹綻放光芒－"
