L29_1 = "At the center of the sinking heavens and earth, the Golden Tree that remained only as a stump shone with light..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "At the center of the sinking heavens and earth, the Golden Tree that remained only as a stump shone with light..."
L28_1.m_Talk_FRA = L29_1
