L30_1 = "EP15_ACT1_INTERLUDE2@225#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 279
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 688
L29_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L30_1 = "세상을 가득 메우던 겨울이 불현듯 물러나고... 봄이 도래했습니다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "m_bTalkCenterFadeIn"
L29_1[L30_1] = true
L30_1 = "世界を埋め尽くしていた冬は突如として終わり……春が訪れました。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "The winter that once filled the world suddenly retreated... and spring arrived."
L29_1.m_Talk_ENG = L30_1
L30_1 = "覆蓋世界的冬天突然退去……春天來臨。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "The winter that once filled the world suddenly retreated... and spring arrived."
L29_1.m_Talk_DEU = L30_1
L30_1 = "The winter that once filled the world suddenly retreated... and spring arrived."
L29_1.m_Talk_FRA = L30_1
