L31_1 = "EP15_ACT1_INTERLUDE2@226#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 280
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 688
L30_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L31_1 = "계절 함께 자라난 새순, 땅의 온갖 것이 수확할 만큼 여무는 가을 무렵."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "m_bTalkCenterFadeIn"
L30_1[L31_1] = true
L31_1 = "季節とともに芽吹いた新芽、大地に育つすべてが収穫の時期を迎える秋頃。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "By autumn, when the new sprouts that grew with the seasons had matured enough for all the land's bounty to be harvested,"
L30_1.m_Talk_ENG = L31_1
L31_1 = "伴隨季節長出的新芽，收獲著大地一切的秋天。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "By autumn, when the new sprouts that grew with the seasons had matured enough for all the land's bounty to be harvested,"
L30_1.m_Talk_DEU = L31_1
