L31_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L32_1 = "<color=#ffd34c>그녀</color>는 한 폭의 그림처럼 세월을 담아, 오늘의 낙원을 만들었습니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "m_bTalkCenterFadeIn"
L31_1[L32_1] = true
L32_1 = "<color=#ffd34c>彼女</color>はまるで一枚の絵のごとく月日を閉じ込め、今の楽園を作りました。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "<color=#ffd34c>She</color>, carrying the passage of time like a painting, created today's Promised Land."
L31_1.m_Talk_ENG = L32_1
L32_1 = "<color=#ffd34c>她</color>就像一幅畫融入歲月，創造了今天的樂園。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "<color=#ffd34c>She</color>, carrying the passage of time like a painting, created today's Promised Land."
L31_1.m_Talk_DEU = L32_1
L32_1 = "<color=#ffd34c>She</color>, carrying the passage of time like a painting, created today's Promised Land."
