L34_1.m_Pos = "C"
L35_1 = "한 차례 잃어버린 현실을 우리 품에 돌려주고, 낙원의 완성이라는 이상을 꿈꾸게 해준..."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "一度は失った現実を再び我らに与え、楽園の完成という理想を夢見ることができるようにしてくれた……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "For the one who returned the reality we once lost to our arms and allowed us to dream of the ideal called the completion of the Promised Land..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "重拾失去的現實，讓我們夢想著完成樂園……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "For the one who returned the reality we once lost to our arms and allowed us to dream of the ideal called the completion of the Promised Land..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "For the one who returned the reality we once lost to our arms and allowed us to dream of the ideal called the completion of the Promised Land..."
