L39_1 = "CITIZEN_ROOT_NPC_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "이렇게 열심히 살아가다 보면 이 낙원에도 밤이 오겠지요?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "こうやって懸命に生きていれば、この楽園にも夜が訪れるでしょうか。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "If we keep living diligently like this, night will come to the Promised Land someday, won't it?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "如果這麼努力生活，這個樂園也會迎來夜晚吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "If we keep living diligently like this, night will come to the Promised Land someday, won't it?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "If we keep living diligently like this, night will come to the Promised Land someday, won't it?"
L38_1.m_Talk_FRA = L39_1
