L39_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L39_1.m_Pos = "C"
L40_1 = "물론입니다. 그날이 오면 우리 모두의 소망도 이루어지겠죠."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "もちろんです。その日が来れば私たちの願いも叶えられるでしょう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Of course. When that day comes, all our wishes will be fulfilled as well."
L39_1.m_Talk_ENG = L40_1
L40_1 = "當然。到了那一天，我們所有的願望都會實現。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "Of course. When that day comes, all our wishes will be fulfilled as well."
L39_1.m_Talk_DEU = L40_1
