L45_1 = "궁금한 것이 있사옵니다, 아버지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "質問がございます、お父様。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "There is something I wish to ask, Father."
L44_1.m_Talk_ENG = L45_1
L45_1 = "父親，我有個問題。"
