L46_1 = "EP15_ACT1_INTERLUDE2@237#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 295
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 688
L45_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_LAUGH"
L45_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L45_1.m_Pos = "C"
L46_1 = "뭐가 궁금하니? 에클레시아."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "何が知りたいんだい？　エクレシア。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "What is it you wish to know, Ecclesia?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "什麼問題，艾可露西亞？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "What is it you wish to know, Ecclesia?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "What is it you wish to know, Ecclesia?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP15_ACT1_INTERLUDE2@238#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 296
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 688
L46_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_IDLE"
L46_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L46_1.m_Pos = "C"
L47_1 = "낙원이 완성되기 위해선 어째서 밤이 필요한 것이옵니까?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "楽園が完成するためには、どうして夜が必要なのでございますか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Why must night exist for the Promised Land to be complete?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "為什麼需要夜晚完成樂園？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "Why must night exist for the Promised Land to be complete?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Why must night exist for the Promised Land to be complete?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP15_ACT1_INTERLUDE2@239#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 297
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 688
L47_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L47_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L47_1.m_Pos = "C"
L48_1 = "저희는 어둠이 없어도 이토록 잘 살아가고 있는데 말입니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "わたくしたちは闇がなくてもこのように問題なく生きております。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "We are living perfectly well even without darkness."
L47_1.m_Talk_ENG = L48_1
L48_1 = "我們即使沒有黑暗，也過得很好啊。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "We are living perfectly well even without darkness."
L47_1.m_Talk_DEU = L48_1
L48_1 = "We are living perfectly well even without darkness."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP15_ACT1_INTERLUDE2@240#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 298
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 688
L48_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_PRIDE"
L48_1.m_Face = L49_1
L48_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L48_1.m_Pos = "C"
L49_1 = "모든 것엔 양면이 있어야 하는 법이니까."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "すべてには両面が必要だからね。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Everything must have two sides."
L48_1.m_Talk_ENG = L49_1
L49_1 = "因為萬物都有兩面性。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "Everything must have two sides."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Everything must have two sides."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP15_ACT1_INTERLUDE2@241#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 299
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 688
L49_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_PRIDE"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L49_1.m_Pos = "C"
L50_1 = "어둠 없이 빛만이 존재하는 세상은 반쪽짜리일 뿐이기 때문이란다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "闇がなく光だけが存在している世界は不完全なんだよ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "A world where only light exists without darkness is only half complete."
L49_1.m_Talk_ENG = L50_1
L50_1 = "沒有黑暗只有光的世界，只是一半的世界而已。"
