L3_1.m_Pos = "C"
L4_1 = "더 이상 누구도 죽길 바라지 않았던 어떤 <color=#ffd34c>의지</color>란다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "もう誰も死なないことを願っていたある種の<color=#ffd34c>意志</color>なんだよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Because of a certain <color=#ffd34c>will</color> that wished for no one to die ever again."
L3_1.m_Talk_ENG = L4_1
L4_1 = "那是……不希望再有人死去的某種<color=#ffd34c>意志</color>。"
