L5_1 = "EP15_ACT1_INTERLUDE2@246#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 304
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 688
