L4_1.m_Face = "UNIT_LAUGH"
L4_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L4_1.m_Pos = "C"
L5_1 = "하지만 낙원이 완벽해지기 위해선, 언젠가 그 죽음 또한 필요해지겠지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "でも楽園を完璧なものにするためには、いつかその死も必要となるだろうね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But for the Promised Land to become perfect, someday even that death will become necessary."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但為了讓樂園完美，終有一天，也會需要死亡。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "But for the Promised Land to become perfect, someday even that death will become necessary."
L4_1.m_Talk_DEU = L5_1
L5_1 = "But for the Promised Land to become perfect, someday even that death will become necessary."
L4_1.m_Talk_FRA = L5_1
