L5_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L5_1.m_Pos = "C"
L6_1 = "낙원이 완벽해진다는 게 어떤 의미인지, 아직도 잘 모르겠사옵니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "楽園を完璧なものにするというのがどういう意味なのか、まだよく分かりません。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I still don't quite understand what it means for the Promised Land to become perfect."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我還是不太明白，樂園完美到底是什麼意思。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "I still don't quite understand what it means for the Promised Land to become perfect."
L5_1.m_Talk_DEU = L6_1
L6_1 = "I still don't quite understand what it means for the Promised Land to become perfect."
L5_1.m_Talk_FRA = L6_1
