L6_1.m_Pos = "C"
L7_1 = "완벽이란 말 자체엔 아무런 의미도 없단다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "完璧という言葉自体には何の意味もない。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "The word perfection itself has no meaning."
