L8_1 = "EP15_ACT1_INTERLUDE2@249#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 307
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 688
L7_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L7_1.m_bWaitClick = true
