L7_1.m_Face = L8_1
L7_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L7_1.m_Pos = "C"
L8_1 = "그것을 정의하고 추구하려는 것 자체가 불완전하고, 상대적이기 때문이지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "それを定義し追及しようとすること自体が不完全であり、相対的だからだ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Because defining it and striving for it is itself imperfect and relative."
L7_1.m_Talk_ENG = L8_1
L8_1 = "去定義並追求它本身就是不完美的，因為它們是相對的。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "Because defining it and striving for it is itself imperfect and relative."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Because defining it and striving for it is itself imperfect and relative."
L7_1.m_Talk_FRA = L8_1
