L9_1 = "EP15_ACT1_INTERLUDE2@250#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 308
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 688
L8_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_IDLE"
L8_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L8_1.m_Pos = "C"
L9_1 = "그렇기 때문에 모든 존재는 완벽해지고 싶은 욕망을 가지고 살아가는 거야."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "だからこそ、すべての存在は完璧になりたいという欲望を抱いて生きているんだよ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "That is why all beings live with the desire to become perfect."
L8_1.m_Talk_ENG = L9_1
L9_1 = "所以所有存在才會懷抱想變完美的欲望活著。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "That is why all beings live with the desire to become perfect."
L8_1.m_Talk_DEU = L9_1
L9_1 = "That is why all beings live with the desire to become perfect."
L8_1.m_Talk_FRA = L9_1
