L10_1 = "EP15_ACT1_INTERLUDE2@251#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 309
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 688
L9_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_IDLE"
L9_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L9_1.m_Pos = "C"
L10_1 = "한 차례 종말을 경험했기에- 누구보다 살아가고 싶고, 복수하길 바라는 낙원의 주민들처럼."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "一度終末を経験したからこそ……誰よりも生きたいし、復讐したいと願う楽園の住民たちのようにね。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Just like the residents of the Promised Land, who experienced the end of the world once and now wish to live more than anyone else... and to take revenge."
L9_1.m_Talk_ENG = L10_1
L10_1 = "因為經歷過一次末日－所以他們像樂園居民一樣比誰都想活下去，也渴望復仇。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "Just like the residents of the Promised Land, who experienced the end of the world once and now wish to live more than anyone else... and to take revenge."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Just like the residents of the Promised Land, who experienced the end of the world once and now wish to live more than anyone else... and to take revenge."
L9_1.m_Talk_FRA = L10_1
