L10_1.m_Pos = "C"
L11_1 = "낙원의 사람들에게 완벽은... 복수인 것이옵니까?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "楽園の人々にとって完璧とは……復讐なのですか？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "For the people of the Promised Land... does perfection mean revenge?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "對樂園的人來說，完美……就是復仇嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "For the people of the Promised Land... does perfection mean revenge?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "For the people of the Promised Land... does perfection mean revenge?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP15_ACT1_INTERLUDE2@253#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 311
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 688
L11_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L11_1.m_bWaitClick = true
