L11_1.m_Face = "UNIT_SERIOUS"
L11_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L11_1.m_Pos = "C"
L12_1 = "우리는 언젠가 이 낙원에 밤이 오길 기다리지."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "僕たちはいつかはこの楽園に訪れる夜を待っているんだ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "We are waiting for the day when night comes here."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我們一直等待樂園迎來夜晚。"
