L13_1 = "EP15_ACT1_INTERLUDE2@254#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 312
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 688
L12_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_SERIOUS"
L12_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L12_1.m_Pos = "C"
L13_1 = "우리의 오랜 정적을 우리 손으로 죽일 것이라는, 황금나무의 예언을 완성하기 위해."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "古い政敵を自分たちの手で殺すだろうという、黄金の木の予言を完成するために。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "To fulfill the prophecy of the Golden Tree that says we will kill our ancient foe with our own hands."
L12_1.m_Talk_ENG = L13_1
L13_1 = "為了完成黃金樹的預言，親手終結我們長久的敵人。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "To fulfill the prophecy of the Golden Tree that says we will kill our ancient foe with our own hands."
L12_1.m_Talk_DEU = L13_1
L13_1 = "To fulfill the prophecy of the Golden Tree that says we will kill our ancient foe with our own hands."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP15_ACT1_INTERLUDE2@255#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 313
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 688
L13_1.m_CutScenStrID = "EP15_ACT1_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SERIOUS"
L13_1.m_CharStrID = "DEMON_VELES_NPC_NULL"
L13_1.m_Pos = "C"
L14_1 = "우리 고향을 멸망시킨, 마왕 타기리온에게 복수할 순간을 위해."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "僕たちの故郷を滅亡させた、魔王タギリオンに復讐する瞬間のためにね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "For the moment when we take revenge on the Demon Lord Thagirion who destroyed our homeland."
L13_1.m_Talk_ENG = L14_1
